public class TextDecoratorsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String render(Text text) {
        try {
            return text.render();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("PlainText renders its value (provided code)", "hi",
                render(new PlainText("hi")));
        check("Upper alone", "HI",
                render(new TextDecorators.Upper(new PlainText("hi"))));
        check("Exclaim alone", "hi!",
                render(new TextDecorators.Exclaim(new PlainText("hi"))));
        check("Exclaim over Upper", "HI!",
                render(new TextDecorators.Exclaim(
                        new TextDecorators.Upper(new PlainText("hi")))));
        check("Upper over Exclaim upper-cases the whole thing", "OK!",
                render(new TextDecorators.Upper(
                        new TextDecorators.Exclaim(new PlainText("ok")))));
        check("double Exclaim stacks", "a!!",
                render(new TextDecorators.Exclaim(
                        new TextDecorators.Exclaim(new PlainText("a")))));
        check("deep chain", "WOW!!",
                render(new TextDecorators.Exclaim(
                        new TextDecorators.Exclaim(
                                new TextDecorators.Upper(new PlainText("wow"))))));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

