interface Text {
    String render();
}

class PlainText implements Text {
    private final String value;

    PlainText(String value) {
        this.value = value;
    }

    public String render() {
        return value;
    }
}

public class TextDecorators {

    public static class Upper implements Text {
        private final Text inner;

        public Upper(Text inner) {
            this.inner = inner;
        }

        public String render() {
            return inner.render().toUpperCase();
        }
    }

    public static class Exclaim implements Text {
        private final Text inner;

        public Exclaim(Text inner) {
            this.inner = inner;
        }

        public String render() {
            return inner.render() + "!";
        }
    }
}
